package main

import "fmt"

func describe(i any) {
	// comma-ok form: never panics, reports success in ok
	if s, ok := i.(string); ok {
		fmt.Printf("string of length %d: %q\n", len(s), s)
		return
	}
	if n, ok := i.(int); ok {
		fmt.Printf("int doubled: %d\n", n*2)
		return
	}
	fmt.Printf("unhandled type %T\n", i)
}

func main() {
	describe("hello") // matches the string case
	describe(21)       // matches the int case
	describe(3.14)     // matches neither -> prints the type

	// Single-result form: SAFE only when the type is guaranteed.
	var i any = "go"
	s := i.(string) // ok, i really is a string
	fmt.Println("asserted:", s)

	// The next line WOULD PANIC if uncommented, because i is a string, not int:
	//   n := i.(int)
	// panic: interface conversion: interface {} is string, not int
}

package main

import "fmt"

func classify(i any) string {
	switch v := i.(type) {
	case nil:
		// matches only the nil interface value (no dynamic type)
		return "nil interface"
	case int:
		// v is an int here
		return fmt.Sprintf("int=%d", v)
	case string:
		// v is a string here
		return fmt.Sprintf("string=%q len=%d", v, len(v))
	case float32, float64:
		// multi-type case: v keeps the interface type (any), not a concrete float
		return fmt.Sprintf("some float, %T", v)
	case bool:
		return fmt.Sprintf("bool=%t", v)
	default:
		// any dynamic type not listed above
		return fmt.Sprintf("unknown type %T", v)
	}
}

func main() {
	fmt.Println(classify(nil))
	fmt.Println(classify(7))
	fmt.Println(classify("hi"))
	fmt.Println(classify(2.5))      // float64 literal -> multi-type case
	fmt.Println(classify(float32(1)))
	fmt.Println(classify(true))
	fmt.Println(classify([]byte{1})) // hits default
}

package main

import (
	"errors"
	"fmt"
)

// A type that optionally reports whether it is temporary.
type temporaryError struct{ msg string }

func (e *temporaryError) Error() string   { return e.msg }
func (e *temporaryError) Temporary() bool { return true }

type permanentError struct{ msg string }

func (e *permanentError) Error() string { return e.msg }

// isTemporary probes for an optional Temporary() bool method via an
// ad-hoc interface assertion -- the value need not name any interface.
func isTemporary(err error) bool {
	te, ok := err.(interface{ Temporary() bool })
	return ok && te.Temporary()
}

func main() {
	var e1 error = &temporaryError{"timeout"}
	var e2 error = &permanentError{"not found"}

	fmt.Println("e1 temporary:", isTemporary(e1)) // implements Temporary()
	fmt.Println("e2 temporary:", isTemporary(e2)) // does not

	// errors.As is the standard library's type-assertion-on-error-chains:
	// it walks the wrapped chain and assigns the first matching type.
	wrapped := fmt.Errorf("call failed: %w", &temporaryError{"reset"})
	var target *temporaryError
	if errors.As(wrapped, &target) {
		fmt.Println("errors.As found temporaryError:", target.Error())
	}
}
